macro_rules! deps {
    () => {
        ByteClasses!();
        DFA!();
        OwnedDFA!();
        StartKind!();
        Start!();
        StartByteMap!();
    };
}

macro_rules! impl_21 {
    () => {
        deps!();
        impl < T : AsRef < [u32] > > DFA < T > { # [doc = " Cheaply return a borrowed version of this dense DFA. Specifically,"] # [doc = " the DFA returned always uses `&[u32]` for its transition table."] pub fn as_ref (& self) -> DFA < & '_ [u32] > { DFA { tt : self . tt . as_ref () , st : self . st . as_ref () , ms : self . ms . as_ref () , special : self . special , accels : self . accels () , pre : self . pre . clone () , quitset : self . quitset , flags : self . flags , } } # [doc = " Return an owned version of this sparse DFA. Specifically, the DFA"] # [doc = " returned always uses `Vec<u32>` for its transition table."] # [doc = ""] # [doc = " Effectively, this returns a dense DFA whose transition table lives on"] # [doc = " the heap."] # [cfg (feature = "alloc")] pub fn to_owned (& self) -> OwnedDFA { DFA { tt : self . tt . to_owned () , st : self . st . to_owned () , ms : self . ms . to_owned () , special : self . special , accels : self . accels () . to_owned () , pre : self . pre . clone () , quitset : self . quitset , flags : self . flags , } } # [doc = " Returns the starting state configuration for this DFA."] # [doc = ""] # [doc = " The default is [`StartKind::Both`], which means the DFA supports both"] # [doc = " unanchored and anchored searches. However, this can generally lead to"] # [doc = " bigger DFAs. Therefore, a DFA might be compiled with support for just"] # [doc = " unanchored or anchored searches. In that case, running a search with"] # [doc = " an unsupported configuration will panic."] pub fn start_kind (& self) -> StartKind { self . st . kind } # [doc = " Returns the start byte map used for computing the `Start` configuration"] # [doc = " at the beginning of a search."] pub (crate) fn start_map (& self) -> & StartByteMap { & self . st . start_map } # [doc = " Returns true only if this DFA has starting states for each pattern."] # [doc = ""] # [doc = " When a DFA has starting states for each pattern, then a search with the"] # [doc = " DFA can be configured to only look for anchored matches of a specific"] # [doc = " pattern. Specifically, APIs like [`Automaton::try_search_fwd`] can"] # [doc = " accept a non-None `pattern_id` if and only if this method returns true."] # [doc = " Otherwise, calling `try_search_fwd` will panic."] # [doc = ""] # [doc = " Note that if the DFA has no patterns, this always returns false."] pub fn starts_for_each_pattern (& self) -> bool { self . st . pattern_len . is_some () } # [doc = " Returns the equivalence classes that make up the alphabet for this DFA."] # [doc = ""] # [doc = " Unless [`Config::byte_classes`] was disabled, it is possible that"] # [doc = " multiple distinct bytes are grouped into the same equivalence class"] # [doc = " if it is impossible for them to discriminate between a match and a"] # [doc = " non-match. This has the effect of reducing the overall alphabet size"] # [doc = " and in turn potentially substantially reducing the size of the DFA's"] # [doc = " transition table."] # [doc = ""] # [doc = " The downside of using equivalence classes like this is that every state"] # [doc = " transition will automatically use this map to convert an arbitrary"] # [doc = " byte to its corresponding equivalence class. In practice this has a"] # [doc = " negligible impact on performance."] pub fn byte_classes (& self) -> & ByteClasses { & self . tt . classes } # [doc = " Returns the total number of elements in the alphabet for this DFA."] # [doc = ""] # [doc = " That is, this returns the total number of transitions that each state"] # [doc = " in this DFA must have. Typically, a normal byte oriented DFA would"] # [doc = " always have an alphabet size of 256, corresponding to the number of"] # [doc = " unique values in a single byte. However, this implementation has two"] # [doc = " peculiarities that impact the alphabet length:"] # [doc = ""] # [doc = " * Every state has a special \"EOI\" transition that is only followed"] # [doc = " after the end of some haystack is reached. This EOI transition is"] # [doc = " necessary to account for one byte of look-ahead when implementing"] # [doc = " things like `\\b` and `$`."] # [doc = " * Bytes are grouped into equivalence classes such that no two bytes in"] # [doc = " the same class can distinguish a match from a non-match. For example,"] # [doc = " in the regex `^[a-z]+$`, the ASCII bytes `a-z` could all be in the"] # [doc = " same equivalence class. This leads to a massive space savings."] # [doc = ""] # [doc = " Note though that the alphabet length does _not_ necessarily equal the"] # [doc = " total stride space taken up by a single DFA state in the transition"] # [doc = " table. Namely, for performance reasons, the stride is always the"] # [doc = " smallest power of two that is greater than or equal to the alphabet"] # [doc = " length. For this reason, [`DFA::stride`] or [`DFA::stride2`] are"] # [doc = " often more useful. The alphabet length is typically useful only for"] # [doc = " informational purposes."] pub fn alphabet_len (& self) -> usize { self . tt . alphabet_len () } # [doc = " Returns the total stride for every state in this DFA, expressed as the"] # [doc = " exponent of a power of 2. The stride is the amount of space each state"] # [doc = " takes up in the transition table, expressed as a number of transitions."] # [doc = " (Unused transitions map to dead states.)"] # [doc = ""] # [doc = " The stride of a DFA is always equivalent to the smallest power of 2"] # [doc = " that is greater than or equal to the DFA's alphabet length. This"] # [doc = " definition uses extra space, but permits faster translation between"] # [doc = " premultiplied state identifiers and contiguous indices (by using shifts"] # [doc = " instead of relying on integer division)."] # [doc = ""] # [doc = " For example, if the DFA's stride is 16 transitions, then its `stride2`"] # [doc = " is `4` since `2^4 = 16`."] # [doc = ""] # [doc = " The minimum `stride2` value is `1` (corresponding to a stride of `2`)"] # [doc = " while the maximum `stride2` value is `9` (corresponding to a stride of"] # [doc = " `512`). The maximum is not `8` since the maximum alphabet size is `257`"] # [doc = " when accounting for the special EOI transition. However, an alphabet"] # [doc = " length of that size is exceptionally rare since the alphabet is shrunk"] # [doc = " into equivalence classes."] pub fn stride2 (& self) -> usize { self . tt . stride2 } # [doc = " Returns the total stride for every state in this DFA. This corresponds"] # [doc = " to the total number of transitions used by each state in this DFA's"] # [doc = " transition table."] # [doc = ""] # [doc = " Please see [`DFA::stride2`] for more information. In particular, this"] # [doc = " returns the stride as the number of transitions, where as `stride2`"] # [doc = " returns it as the exponent of a power of 2."] pub fn stride (& self) -> usize { self . tt . stride () } # [doc = " Returns the memory usage, in bytes, of this DFA."] # [doc = ""] # [doc = " The memory usage is computed based on the number of bytes used to"] # [doc = " represent this DFA."] # [doc = ""] # [doc = " This does **not** include the stack size used up by this DFA. To"] # [doc = " compute that, use `std::mem::size_of::<dense::DFA>()`."] pub fn memory_usage (& self) -> usize { self . tt . memory_usage () + self . st . memory_usage () + self . ms . memory_usage () + self . accels . memory_usage () } }
    };
}

impl_21!();